jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["eli-admin"];
  if (!bundle) return;

  _installRealAdmin(eli);

  function _installRealAdmin(eli) {
    var STORE_CONFIG = "config";
    var apiVersion = 1;
    var APPLIED_KEY_PREFIX = "_admin_applied_";

    // 2026-05-23c: register fleet-managed settings. eli-admin is boot-tier
    // and runs on every user's machine, so this is the canonical spot for
    // admin-pushable settings that aren't already registered by the kernel.
    // Two groups:
    //   plain (adminPushable: true)      — telemetry includes current value,
    //                                      pushable via set_setting
    //   encrypted (adminPushable: "encrypted") — telemetry excludes value,
    //                                            pushable only via
    //                                            set_setting_encrypted
    // Excluded entirely (NOT registered): api_key, user_name, user_email.
    _registerFleetSettings(eli);

    function _registerFleetSettings(eli) {
      if (!eli || !eli.settings || typeof eli.settings.register !== "function") return;
      var SETTINGS_BLOB = "eli_user_settings"; // v2 JSON blob field carrier

      // 8 plain user prefs (stored on eli_user_settings blob, or own LS key).
      eli.settings.register("light_mode", {
        default: false, type: "boolean",
        storage: { type: "ls_blob_field", key: SETTINGS_BLOB, field: "lightMode" },
        adminPushable: true,
        describe: "Light theme toggle",
      });
      eli.settings.register("header_theme_index", {
        default: 0, type: "number",
        storage: { type: "ls_blob_field", key: SETTINGS_BLOB, field: "headerThemeIndex" },
        adminPushable: true,
        describe: "Header gradient theme index",
      });
      eli.settings.register("minimize_feed", {
        default: false, type: "boolean",
        storage: { type: "ls_blob_field", key: SETTINGS_BLOB, field: "minimizeFeedOnStart" },
        adminPushable: true,
        describe: "Minimize activity feed on start",
      });
      eli.settings.register("auto_hide_sidebar", {
        default: false, type: "boolean",
        storage: { type: "ls_blob_field", key: SETTINGS_BLOB, field: "autoHideSidebar" },
        adminPushable: true,
        describe: "Auto-hide sidebar",
      });
      eli.settings.register("auto_expand_window", {
        default: false, type: "boolean",
        storage: { type: "ls_blob_field", key: SETTINGS_BLOB, field: "autoExpandWindow" },
        adminPushable: true,
        describe: "Auto-expand window on launch",
      });
      eli.settings.register("auto_check_tools", {
        default: true, type: "boolean",
        storage: { type: "ls_blob_field", key: SETTINGS_BLOB, field: "autoCheckTools" },
        adminPushable: true,
        describe: "Auto-check for tool updates on boot",
      });
      eli.settings.register("show_expand_pill", {
        default: true, type: "boolean",
        storage: { type: "ls_blob_field", key: SETTINGS_BLOB, field: "showExpandPill" },
        adminPushable: true,
        describe: "Show 'click to expand' pill in narrow layout",
      });
      eli.settings.register("language", {
        default: "en", type: "string",
        storage: { type: "ls_key", key: "eli_language" },
        adminPushable: true,
        describe: "UI language code",
      });

      // 6 encrypted/sensitive settings — current values stay local; admin
      // can push new ones as ciphertext via set_setting_encrypted. Telemetry
      // never includes these (strict adminPushable === true filter at
      // eli_telemetry/init.js).
      eli.settings.register("admin_password", {
        default: null, type: "string",
        storage: { type: "ls_key", key: "eli_admin_password" },
        adminPushable: "encrypted",
        describe: "Admin auth + encryption root (the decrypt key itself)",
      });
      eli.settings.register("github_pat", {
        default: null, type: "string",
        storage: { type: "ls_key", key: "eli_user_github_pat" },
        adminPushable: "encrypted",
        describe: "GitHub PAT for eli-data CDN reads/writes",
      });
      eli.settings.register("github_repo", {
        default: null, type: "string",
        storage: { type: "ls_key", key: "eli_github_repo" },
        adminPushable: "encrypted",
        describe: "GitHub owner/repo for CDN (e.g. apndrewn/eli-data)",
      });
      eli.settings.register("github_branch", {
        default: null, type: "string",
        storage: { type: "ls_key", key: "eli_github_branch" },
        adminPushable: "encrypted",
        describe: "GitHub branch (typically main)",
      });
      eli.settings.register("manifest_url", {
        default: null, type: "string",
        storage: { type: "ls_key", key: "eli_manifest_url" },
        adminPushable: "encrypted",
        describe: "Tools manifest URL",
      });
      eli.settings.register("lib_cipher", {
        default: null, type: "string",
        storage: { type: "ls_key", key: "eli_lib_cipher" },
        adminPushable: "encrypted",
        describe: "Proprietary library cipher key",
      });
    }

    // Default to raw.githubusercontent.com. admin-overrides.json is small
    // and needs freshness; jsdelivr's CDN was holding stale cache for
    // hours even after purge calls returned "finished" (seen 2026-05-13).
    // Raw is rate-limited (60 anonymous req/h, 5000 authenticated) but
    // a 30-min poll cadence is well inside that. jsdelivr stays as the
    // fallback in case raw rate-limits or has a transient outage.
    function _deriveOverridesUrl() {
      var repo = eli.compat.lsGet("eli_github_repo");
      var branch = eli.compat.lsGet("eli_github_branch");
      if (!repo || !branch) return null;
      return "https://raw.githubusercontent.com/" + repo + "/" + branch + "/admin-overrides.json";
    }

    // Case-insensitive tool-id resolver — admin overrides sometimes use
    // display casing ("DocuScrub") while installed bundles use lowercase
    // ids ("docuscrub"). Fall back to a scan when the exact id misses,
    // and log when no match is found so silent failures surface.
    function _resolveToolId(idOrName) {
      if (!idOrName) return Promise.resolve(null);
      return eli.tools.get(idOrName).then(function (b) {
        if (b) return idOrName;
        // Exact miss — try case-insensitive scan of installed bundles.
        return eli.tools.list().then(function (rows) {
          var needle = String(idOrName).toLowerCase();
          var hit = (rows || []).find(function (r) {
            return r && r.id && r.id.toLowerCase() === needle;
          });
          if (hit) {
            eli.log.event("admin", "tool_id_normalized", { from: idOrName, to: hit.id });
            return hit.id;
          }
          eli.log.event("admin", "tool_id_not_found", { requested: idOrName });
          return null;
        });
      });
    }
    var ACTIONS = {
      disable_tool: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return _resolveToolId(a.toolId).then(function (id) {
          if (!id) return false;
          return eli.tools.disable(id).then(function () { return true; });
        });
      },
      enable_tool: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return _resolveToolId(a.toolId).then(function (id) {
          if (!id) return false;
          return eli.tools.enable(id).then(function () { return true; });
        });
      },
      clear_idb_row: function (a) {
        if (!a.store || a.id == null) return Promise.resolve(false);
        return eli.storage.delete(a.store, a.id).then(function () { return true; });
      },
      clear_idb_store: function (a) {
        if (!a.store) return Promise.resolve(false);
        return eli.storage.clearStore(a.store).then(function () { return true; });
      },
      clear_localstorage_key: function (a) {
        if (!a.key) return Promise.resolve(false);
        eli.compat.lsRemove(a.key);
        return Promise.resolve(true);
      },
      set_config: function (a) {
        if (!a.key) return Promise.resolve(false);
        return eli.storage.put(STORE_CONFIG, { key: a.key, value: a.value }).then(function () { return true; });
      },
      // 2026-05-22: set_setting routes through eli.settings with proper
      // layer semantics. Three modes via `force`:
      //   force: true      → admin force layer (locks the field, overrides user pref)
      //   force: "reset"   → writes to user pref layer (user can change after)
      //   force: false (default) → admin soft layer (only applies if user pref empty)
      // After applying, also emits an activity feed entry so colleagues
      // can see what changed and when in their dashboard.
      set_setting: function (a) {
        if (!a.key || !eli.settings || typeof eli.settings.set !== "function") {
          return Promise.resolve(false);
        }
        // 2026-05-23c: refuse plain set_setting for "encrypted"-tagged
        // settings. Defense in depth — a misconfigured override that tried
        // to push api_key / admin_password / etc. in plaintext to the
        // public CDN would otherwise leak. Use set_setting_encrypted.
        try {
          var dump = (typeof eli.settings.dump === "function") ? eli.settings.dump() : null;
          var entry = dump && dump[a.key];
          if (entry && entry.adminPushable === "encrypted") {
            eli.log.event("admin", "plain_push_rejected_encrypted", { key: a.key });
            return Promise.reject(new Error("setting requires set_setting_encrypted"));
          }
        } catch (_e) { /* tolerate — proceed to set() */ }
        var layer;
        var modeLabel;
        if (a.force === true) {
          layer = eli.settings.LAYER_ADMIN_FORCE;
          modeLabel = "forced (locked)";
        } else if (a.force === "reset") {
          layer = eli.settings.LAYER_USER;
          modeLabel = "reset (editable)";
        } else {
          layer = eli.settings.LAYER_ADMIN_SOFT;
          modeLabel = "default (suggested)";
        }
        var ok = eli.settings.set(a.key, a.value, { layer: layer });
        // 2026-05-23c+: reject (not resolve false) so applyAll's catch
        // marks the action as failed and skips writing the applied marker.
        // Resolving false would still count as "applied" — silent failure.
        // Common cause: key isn't registered yet on the target (e.g.,
        // eli-admin's _registerFleetSettings hasn't run, or validator
        // rejected the value). Override re-fires next poll, by which
        // time registration may have completed.
        if (!ok) return Promise.reject(new Error("settings.set rejected key=" + a.key));
        // Activity feed audit trail — surfaces the admin push in the
        // colleague's home dashboard. Slim entry; payload omitted by
        // the activity feed's persistence layer anyway.
        try {
          if (eli.activity && typeof eli.activity.add === "function") {
            eli.activity.add({
              type: "admin.setting",
              icon: "⚙️",
              label: "Setting Updated by Admin",
              summary: a.key + " → " + JSON.stringify(a.value) + " (" + modeLabel + ")",
              timestamp: Date.now(),
            });
          }
        } catch (_e) { /* tolerate */ }
        return Promise.resolve(true);
      },
      // 2026-05-22: clear any admin override (force or soft) for a key.
      // The user's underlying preference is preserved — clearing the admin
      // layer just unshadows it. Used when revoking a previously-pushed
      // override (e.g., admin-overrides.json removes the entry).
      clear_setting_override: function (a) {
        if (!a.key || !eli.settings || typeof eli.settings.set !== "function") {
          return Promise.resolve(false);
        }
        // Capture the return value too — if the key isn't registered,
        // clear can't do anything and should surface as failure so the
        // revert override re-fires next poll.
        var ok = eli.settings.set(a.key, null, { layer: eli.settings.LAYER_CLEAR_ADMIN });
        if (!ok) return Promise.reject(new Error("clear failed; key not registered: " + a.key));
        return Promise.resolve(true);
      },
      // 2026-05-23c: encrypted setting push. Sensitive values (admin_password,
      // github_pat, etc.) are written as ciphertext to admin-overrides.json
      // on the public CDN. Target decrypts locally with its admin_password.
      //
      // Payload shape: { type, key, ciphertext: {v,salt,iv,ct}, force? }
      //   force: same semantics as set_setting (true | "reset" | undefined)
      //
      // Returns Promise.reject on decrypt failure so applyAll skips writing
      // the applied-marker — override will retry next poll (handles the
      // password-rotation in-flight case).
      set_setting_encrypted: function (a) {
        if (!a.key || !a.ciphertext || !eli.settings || typeof eli.settings.set !== "function") {
          return Promise.resolve(false);
        }
        if (typeof window._eliDecryptFromRepo !== "function") {
          return Promise.reject(new Error("decrypt helper unavailable"));
        }
        // Defense in depth: refuse to write encrypted ciphertext into a
        // setting that wasn't tagged as encrypted-only. Prevents smuggling.
        try {
          var dump = (typeof eli.settings.dump === "function") ? eli.settings.dump() : null;
          var entry = dump && dump[a.key];
          if (entry && entry.adminPushable !== "encrypted") {
            eli.log.event("admin", "encrypted_push_rejected_wrong_tag", { key: a.key, tag: entry.adminPushable });
            return Promise.reject(new Error("setting is not adminPushable:encrypted"));
          }
        } catch (_e) { /* tolerate — let decrypt path decide */ }
        var pass = "";
        try { pass = String(eli.compat.lsGet("eli_admin_password") || "").trim(); } catch (_e) {}
        if (!pass) {
          eli.log.event("admin", "encrypted_push_no_password", { key: a.key });
          return Promise.reject(new Error("no admin_password available to decrypt"));
        }
        return window._eliDecryptFromRepo(pass, a.ciphertext).then(function (envelope) {
          // Envelope shape: { v: 1, value: <plaintext> }. Future-proof if we
          // ever need to bundle metadata alongside the value.
          var plaintext = (envelope && Object.prototype.hasOwnProperty.call(envelope, "value"))
            ? envelope.value
            : envelope;
          var layer;
          var modeLabel;
          if (a.force === true) {
            layer = eli.settings.LAYER_ADMIN_FORCE;
            modeLabel = "forced (locked)";
          } else if (a.force === "reset") {
            layer = eli.settings.LAYER_USER;
            modeLabel = "reset (editable)";
          } else {
            layer = eli.settings.LAYER_ADMIN_SOFT;
            modeLabel = "default (suggested)";
          }
          var ok = eli.settings.set(a.key, plaintext, { layer: layer });
          // Same reject-on-falsy semantics as set_setting — silent
          // "applied but didn't write" is the worst failure mode.
          if (!ok) return Promise.reject(new Error("settings.set rejected encrypted key=" + a.key));
          try {
            if (eli.activity && typeof eli.activity.add === "function") {
              // NEVER include plaintext value in the activity feed — only
              // surface that an encrypted push landed. Plaintext stays on
              // the target machine; the audit trail says "something
              // changed" without leaking what.
              eli.activity.add({
                type: "admin.setting",
                icon: "🔐",
                label: "Sensitive Setting Updated by Admin",
                summary: a.key + " (encrypted, " + modeLabel + ")",
                timestamp: Date.now(),
              });
            }
          } catch (_e) { /* tolerate */ }
          return true;
        });
      },
      // 2026-05-23c: dashboard pinning. Mutates eli_dashboard_apps array
      // in localStorage (CATALOG ids, e.g. "app_legal_risks"), then asks
      // the kernel to refresh the dashboard. Returns reject when the
      // tool isn't installed OR its catalog metadata is missing —
      // applyAll then skips the marker so the override re-fires next
      // poll (in case the missing tool is installed in the meantime).
      pin_tool: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return _resolveToolId(a.toolId).then(function (bundleId) {
          if (!bundleId) return Promise.reject(new Error("tool not installed: " + a.toolId));
          var catalogId = _bundleToCatalog(bundleId);
          if (!catalogId) return Promise.reject(new Error("catalog id missing for tool: " + bundleId));
          var pins = _readPins();
          if (pins.indexOf(catalogId) === -1) pins.push(catalogId);
          _writePins(pins);
          _refreshDashboard();
          return true;
        });
      },
      unpin_tool: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return _resolveToolId(a.toolId).then(function (bundleId) {
          if (!bundleId) return Promise.reject(new Error("tool not installed: " + a.toolId));
          var catalogId = _bundleToCatalog(bundleId);
          if (!catalogId) return Promise.reject(new Error("catalog id missing for tool: " + bundleId));
          var pins = _readPins();
          var idx = pins.indexOf(catalogId);
          if (idx !== -1) pins.splice(idx, 1);
          _writePins(pins);
          _refreshDashboard();
          return true;
        });
      },
      force_redownload_tool: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return eli.tools.uninstall(a.toolId).then(function () { return true; });
      },
      // 2026-05-23 (Phase 2): per-user Grant / Revoke / Clear-override
      // for a specific tool. Targets a single user via the override's
      // audience. Writes STORE_CONFIG._admin_user_tool_overrides which
      // kernel matchesAudience consults FIRST (grant forces inclusion,
      // revoke forces exclusion). Each handler then triggers an install
      // or uninstall so the change takes effect immediately rather than
      // waiting for the next sync.
      audience_grant_user: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return _writeAudienceOverride(a.toolId, "grant").then(function () {
          // Force install — installOne is audience-blind, so the grant
          // marker isn't required for the install itself; it's required
          // so future syncs surface updates instead of treating the
          // tool as "not for you."
          if (!eli.tools || typeof eli.tools.installOne !== "function") return true;
          return eli.tools.installOne(a.toolId).then(function () { return true; })
            .catch(function (err) {
              eli.log.event("admin", "grant_install_failed", { toolId: a.toolId, err: err && err.message });
              return true; // marker is in place; next sync will retry
            });
        });
      },
      audience_revoke_user: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return _writeAudienceOverride(a.toolId, "revoke").then(function () {
          if (!eli.tools || typeof eli.tools.uninstall !== "function") return true;
          return eli.tools.uninstall(a.toolId).then(function () { return true; })
            .catch(function (err) {
              eli.log.event("admin", "revoke_uninstall_failed", { toolId: a.toolId, err: err && err.message });
              return true; // marker is in place; future syncs will skip
            });
        });
      },
      audience_clear_user_override: function (a) {
        if (!a.toolId) return Promise.resolve(false);
        return _writeAudienceOverride(a.toolId, null).then(function () { return true; });
      },
      reset_onboarding: function () {
        return eli.storage.delete(STORE_CONFIG, "onboarding_completed").then(function () { return true; });
      },
      notice: function (a) {
        // Return Promise.reject when the dialog can't actually render so
        // applyAll skips writing the applied-marker. Without this, a
        // silent showEliDialog throw burns the override forever.
        try {
          if (a.html && typeof showEliDialog === "function") {
            var ov = showEliDialog({
              variant: "info", icon: "📢",
              title: a.title || "Admin Notice", body: a.html,
              buttons: [{
                label: a.dismissLabel || "OK",
                onclick: function (e, x) { if (x && x.parentNode) x.parentNode.removeChild(x); },
              }],
            });
            // showEliDialog returns the overlay element; if it didn't,
            // something went wrong even without an exception.
            if (!ov) return Promise.reject(new Error("showEliDialog returned null"));
            return Promise.resolve(true);
          }
          if (typeof showToast === "function") {
            showToast(a.message || a.title || "Admin notice", "warn");
            return Promise.resolve(true);
          }
          return Promise.reject(new Error("no dialog/toast available"));
        } catch (e) {
          return Promise.reject(e);
        }
      },
      reload_kernel: function () {
        try { if (typeof location !== "undefined" && location.reload) location.reload(); } catch (e) {}
        return Promise.resolve(true);
      },
      // 2026-05-25: push a Tier-2 survey to the target's pending list.
      // Dispatches into survey_tester's `survey.push` channel (registered
      // by the survey_tester tool). If survey_tester isn't installed on
      // the target, the dispatch resolves to null and we reject so the
      // applied-marker isn't written — override re-fires next poll once
      // the target has the tool. Spec shape mirrors survey_tester's
      // pending row format: { id?, title, description?, questions: [...] }.
      present_survey: function (a) {
        if (!a || !a.spec || typeof a.spec !== "object") {
          return Promise.reject(new Error("present_survey: spec required"));
        }
        if (!eli.dispatch) return Promise.reject(new Error("dispatch unavailable"));
        var p;
        try { p = eli.dispatch("survey", "push", a.spec); }
        catch (e) { return Promise.reject(e); }
        if (!p) {
          // survey_tester not installed → no handler.
          return Promise.reject(new Error("survey_tester not installed on this machine"));
        }
        // p is the Promise returned by _pushFromAdmin in survey_tester.
        return Promise.resolve(p).then(function (ok) {
          if (!ok) return Promise.reject(new Error("survey push returned false"));
          try {
            if (eli.activity && typeof eli.activity.add === "function") {
              eli.activity.add({
                type: "admin.survey",
                icon: "📋",
                label: "Survey Received from Admin",
                summary: (a.spec.title || "(untitled survey)") + " · " + ((a.spec.questions || []).length) + " questions",
                timestamp: Date.now(),
              });
            }
          } catch (_e) {}
          return true;
        });
      },
      // 2026-05-25: data library push actions. Routes through the kernel's
      // eli.tools.uninstallData(id, opts) which knows how to wipe rows +
      // clear stamps based on the manifest entry. redownload_library uses
      // keepRows:true so user retains current data through the gap; the
      // next manifest poll re-fetches the latest version. delete_library
      // wipes rows AND stamps for full removal (will reinstall on next
      // poll if user still matches audience — admin must adjust audience
      // separately if they want it gone permanently).
      redownload_library: function (a) {
        if (!a || !a.libraryId) return Promise.reject(new Error("libraryId required"));
        if (!eli.tools || typeof eli.tools.uninstallData !== "function") {
          return Promise.reject(new Error("uninstallData unavailable"));
        }
        return Promise.resolve(eli.tools.uninstallData(a.libraryId, { keepRows: true }))
          .then(function () {
            try {
              if (eli.activity && typeof eli.activity.add === "function") {
                eli.activity.add({
                  type: "admin.library",
                  icon: "🔄",
                  label: "Library Refresh Requested by Admin",
                  summary: a.libraryId + " — stamps cleared; next manifest poll will re-fetch",
                  timestamp: Date.now(),
                });
              }
            } catch (_e) {}
            return true;
          });
      },
      delete_library: function (a) {
        if (!a || !a.libraryId) return Promise.reject(new Error("libraryId required"));
        if (!eli.tools || typeof eli.tools.uninstallData !== "function") {
          return Promise.reject(new Error("uninstallData unavailable"));
        }
        return Promise.resolve(eli.tools.uninstallData(a.libraryId))
          .then(function () {
            try {
              if (eli.activity && typeof eli.activity.add === "function") {
                eli.activity.add({
                  type: "admin.library",
                  icon: "🗑",
                  label: "Library Deleted by Admin",
                  summary: a.libraryId + " — rows wiped + stamps cleared",
                  timestamp: Date.now(),
                });
              }
            } catch (_e) {}
            return true;
          });
      },
      // 2026-05-25: dashboard layout push actions. set_dashboard_pins
      // replaces the user's pinned-apps list (eli_dashboard_apps) wholesale
      // with the admin-supplied array. reset_dashboard_to_defaults clears
      // the key so catalog defaults take over. Both trigger a dashboard
      // re-render. set_dashboard_pins expects catalog ids (app_xxx form).
      set_dashboard_pins: function (a) {
        if (!a || !Array.isArray(a.pins)) return Promise.reject(new Error("pins[] required"));
        // Defensive: every entry must be a non-empty string. Drop anything
        // that doesn't match the app_* convention.
        var cleaned = a.pins.filter(function (p) {
          return typeof p === "string" && p.indexOf("app_") === 0;
        });
        try {
          eli.compat.lsSet("eli_dashboard_apps", JSON.stringify(cleaned));
        } catch (e) { return Promise.reject(e); }
        // Trigger dashboard re-render so colleague sees the new layout
        // immediately (they may already be on the dashboard view).
        try {
          if (window.eli && window.eli.dashboard && typeof window.eli.dashboard.refresh === "function") {
            window.eli.dashboard.refresh();
          }
        } catch (_e) {}
        try {
          if (eli.activity && typeof eli.activity.add === "function") {
            eli.activity.add({
              type: "admin.dashboard",
              icon: "🎛",
              label: "Dashboard Layout Updated by Admin",
              summary: cleaned.length + " tile" + (cleaned.length === 1 ? "" : "s") + " pinned",
              timestamp: Date.now(),
            });
          }
        } catch (_e) {}
        return Promise.resolve(true);
      },
      reset_dashboard_to_defaults: function () {
        try {
          eli.compat.lsRemove("eli_dashboard_apps");
        } catch (e) { return Promise.reject(e); }
        try {
          if (window.eli && window.eli.dashboard && typeof window.eli.dashboard.refresh === "function") {
            window.eli.dashboard.refresh();
          }
        } catch (_e) {}
        try {
          if (eli.activity && typeof eli.activity.add === "function") {
            eli.activity.add({
              type: "admin.dashboard",
              icon: "🎛",
              label: "Dashboard Reset to Defaults by Admin",
              summary: "your customizations cleared — catalog defaults active",
              timestamp: Date.now(),
            });
          }
        } catch (_e) {}
        return Promise.resolve(true);
      },
      request_stats_dump: function (a) {
        return _consentAndCopy("stats", function () {
          return Promise.resolve({ stats: eli.stats.getAll() });
        }, a);
      },
      request_activity_dump: function (a) {
        return _consentAndCopy("activity", function () {
          return Promise.resolve({ activity: eli.activity.list() });
        }, a);
      },
      request_capture_dump: function (a) {
        return _consentAndCopy("wrongness captures", function () {
          if (eli.wrongness && typeof eli.wrongness.exportJSON === "function") return eli.wrongness.exportJSON();
          return Promise.resolve({ captures: [], flags: [], note: "wrongness viewer not loaded" });
        }, a);
      },
      request_idb_inspection: function (a) {
        return _consentAndCopy("IDB inspection", function () {
          if (eli.diag && typeof eli.diag.report === "function") return eli.diag.report();
          return Promise.resolve({ note: "diag.report not loaded" });
        }, a);
      },
    };

    function _consentAndCopy(label, dataProvider, action) {
      if (typeof eli.ui === "undefined" || typeof eli.ui.confirm !== "function") {
        return Promise.resolve(false);
      }
      return eli.ui.confirm({
        variant: "warning", icon: "🔒",
        title: "Admin Diagnostic Request",
        message: "Admin requested your " + label + ".<br><br>" +
          "Click <b>Send</b> to copy the report to your clipboard. You can paste it back to the admin.<br><br>" +
          "<i>No data is sent automatically.</i>",
        confirmLabel: "Copy to clipboard", cancelLabel: "Decline",
      }).then(function (ok) {
        if (!ok) {
          eli.log.event("admin", "consent_declined", { label: label, overrideId: action.id });
          return false;
        }
        return dataProvider().then(function (data) {
          var json = JSON.stringify(data, null, 2);
          var copyFn = window._eliClipboardWriteOrFallback ||
            function (s) { return navigator.clipboard.writeText(s); };
          return copyFn(json, "Admin requested: " + label).then(function () {
            eli.log.event("admin", "consent_granted_copied", { label: label, overrideId: action.id });
            if (typeof showToast === "function") showToast("Diagnostic ready — see dialog.", "ok");
            return true;
          });
        });
      });
    }

    // 2026-05-23 (Phase 2): per-user tool override writer. Reads the
    // STORE_CONFIG._admin_user_tool_overrides row, sets or clears the
    // entry for the toolId, writes it back, then asks the kernel to
    // re-hydrate its sync cache so matchesAudience sees the change
    // without a reload. Used by audience_grant_user / audience_revoke_user
    // / audience_clear_user_override action handlers above.
    function _writeAudienceOverride(toolId, mode) {
      if (!toolId) return Promise.resolve(null);
      return eli.storage.get("config", "_admin_user_tool_overrides").then(function (row) {
        var value = (row && row.value && typeof row.value === "object") ? row.value : {};
        if (mode === "grant" || mode === "revoke") {
          value[toolId] = mode;
        } else {
          delete value[toolId];
        }
        return eli.storage.put("config", { key: "_admin_user_tool_overrides", value: value }).then(function () {
          if (eli.tools && typeof eli.tools.refreshAudienceOverrides === "function") {
            return eli.tools.refreshAudienceOverrides().then(function () { return value; });
          }
          return value;
        });
      });
    }
    // 2026-05-23c: dashboard pin helpers used by pin_tool / unpin_tool.
    function _readPins() {
      try {
        var raw = eli.compat.lsGet("eli_dashboard_apps");
        if (!raw) return [];
        var parsed = (typeof raw === "string") ? JSON.parse(raw) : raw;
        return Array.isArray(parsed) ? parsed.slice() : [];
      } catch (_e) { return []; }
    }
    function _writePins(arr) {
      try { eli.compat.lsSet("eli_dashboard_apps", JSON.stringify(arr || [])); }
      catch (_e) {}
    }
    function _refreshDashboard() {
      try {
        if (window.eli && window.eli.dashboard && typeof window.eli.dashboard.refresh === "function") {
          window.eli.dashboard.refresh();
        }
      } catch (_e) { /* tolerate */ }
    }
    // 2026-05-23c+: the kernel stores pins as CATALOG ids
    // ("app_legal_risks") but admin_fleet (and the action payload) refers
    // to tools by BUNDLE id ("legal_risks"). Convert before write — silent
    // failure mode is brutal because the handler still reports success.
    function _bundleToCatalog(bundleId) {
      try {
        if (window.eli && window.eli.tools && window.eli.tools._loaded) {
          var b = window.eli.tools._loaded[bundleId];
          if (b && b.catalog && b.catalog.id) return b.catalog.id;
        }
      } catch (_e) {}
      return null;
    }

    function applyAll(overridesDoc) {
      if (!overridesDoc || !Array.isArray(overridesDoc.overrides)) return Promise.resolve(0);
      var user = eli.tools.userIdentity();
      var now = Date.now();
      var applied = 0;
      return overridesDoc.overrides.reduce(function (chain, ov) {
        return chain.then(function () {
          if (!ov || !ov.id) return;
          return eli.storage.get(STORE_CONFIG, APPLIED_KEY_PREFIX + ov.id).then(function (existing) {
            if (existing) return;
            if (ov.expiresAt && Date.parse(ov.expiresAt) < now) {
              eli.log.event("admin", "expired_skipped", { id: ov.id });
              return;
            }
            if (!eli.tools.matchesAudience(ov, user)) return;
            // 2026-05-23c: dependency gate. If ov.dependsOnAppliedId is
            // set, skip until the referenced override has applied. Lets
            // admin chain "rotate admin_password" → "push new PAT" so the
            // new PAT is encrypted with the NEW password (target had to
            // process the password rotation first). Skipping leaves no
            // marker, so this override re-fires next poll.
            var depGate = ov.dependsOnAppliedId
              ? eli.storage.get(STORE_CONFIG, APPLIED_KEY_PREFIX + ov.dependsOnAppliedId)
              : Promise.resolve(true);
            return depGate.then(function (dep) {
              if (ov.dependsOnAppliedId && !dep) {
                eli.log.event("admin", "dep_not_applied_yet", { id: ov.id, dep: ov.dependsOnAppliedId });
                return;
              }
              var actions = Array.isArray(ov.actions) ? ov.actions : [];
              // Track whether any action signaled failure — if so, skip
              // writing the applied-marker so the override re-fires on the
              // next poll. Notably catches the "dialog silently failed to
              // render but marker was written anyway" boot-race case AND
              // the encrypted-push "wrong admin_password" case.
              var anyActionFailed = false;
              return actions.reduce(function (innerChain, action) {
                return innerChain.then(function () {
                  var handler = ACTIONS[action.type];
                  if (!handler) {
                    eli.log.event("admin", "unknown_action", { id: ov.id, type: action.type });
                    anyActionFailed = true;
                    return;
                  }
                  return Promise.resolve(handler(action)).catch(function (err) {
                    anyActionFailed = true;
                    eli.log.event("admin", "action_failed", { id: ov.id, type: action.type, err: err && err.message });
                    return false;
                  });
                });
              }, Promise.resolve()).then(function () {
                if (anyActionFailed) {
                  eli.log.event("admin", "marker_skipped", { id: ov.id });
                  return;
                }
                return eli.storage.put(STORE_CONFIG, {
                  key: APPLIED_KEY_PREFIX + ov.id,
                  appliedAt: now,
                  overrideId: ov.id,
                }).then(function () {
                  applied++;
                  eli.log.event("admin", "override_applied", { id: ov.id });
                });
              });
            });
          });
        });
      }, Promise.resolve()).then(function () { return applied; });
    }

    // Derive the raw.githubusercontent.com fallback URL from a jsdelivr URL.
    // jsdelivr has known cache-lag and intermittent fetch-failure issues
    // (seen 2026-05-13: file pushed to GitHub at T+0, jsdelivr served 404
    // until T+60s+ even after manual purge). Falling back to raw fixes both
    // the cold-cache 404 and the "Failed to fetch from GitHub" cases.
    function _rawFallbackUrl(jsdelivrUrl) {
      // Match: https://cdn.jsdelivr.net/gh/<owner>/<repo>@<branch>/<path>
      var m = /^https:\/\/cdn\.jsdelivr\.net\/gh\/([^/]+)\/([^/@]+)@([^/]+)\/(.+)$/.exec(jsdelivrUrl || "");
      if (!m) return null;
      return "https://raw.githubusercontent.com/" + m[1] + "/" + m[2] + "/" + m[3] + "/" + m[4];
    }
    function fetchOverrides(url) {
      url = url || eli.compat.lsGet("eli_overrides_url") || _deriveOverridesUrl();
      if (!url) return Promise.resolve({ schemaVersion: 1, overrides: [] });
      if (typeof navigator !== "undefined" && navigator.onLine === false) {
        return Promise.reject(new eli.errors.OfflineError("offline"));
      }
      if (typeof fetch === "undefined") {
        return Promise.reject(new eli.errors.KernelError("fetch unavailable"));
      }
      function _tryFetch(u, isFallback) {
        // cache:"no-store" + query-string buster — GitHub's raw URL sends
        // Cache-Control headers that let the browser serve stale empty
        // responses after the file is updated, which silently kills
        // overrides until the cache TTL expires.
        var busted = u + (u.indexOf("?") === -1 ? "?" : "&") + "_t=" + Date.now();
        return fetch(busted, { cache: "no-store" }).then(function (res) {
          if (res.status === 404) {
            if (!isFallback) {
              var raw = _rawFallbackUrl(u);
              if (raw) {
                eli.log.event("admin", "fetch_fallback_raw", { from: u, to: raw });
                return _tryFetch(raw, true);
              }
            }
            return { schemaVersion: 1, overrides: [] };
          }
          if (!res.ok) {
            if (!isFallback) {
              var raw2 = _rawFallbackUrl(u);
              if (raw2) {
                eli.log.event("admin", "fetch_fallback_raw_on_error", { status: res.status, to: raw2 });
                return _tryFetch(raw2, true);
              }
            }
            throw new eli.errors.ToolError("overrides fetch failed: " + res.status);
          }
          return res.json();
        }).catch(function (err) {
          // Network-level failure (DNS, blocked, etc.) — try raw once.
          if (!isFallback) {
            var raw3 = _rawFallbackUrl(u);
            if (raw3) {
              eli.log.event("admin", "fetch_fallback_raw_on_throw", { err: err && err.message, to: raw3 });
              return _tryFetch(raw3, true);
            }
          }
          throw err;
        });
      }
      return _tryFetch(url, false);
    }

    function poll(url) {
      return fetchOverrides(url).then(function (doc) {
        return applyAll(doc).then(function (n) {
          if (n > 0) eli.log.event("admin", "polled", { applied: n });
          return n;
        });
      }).catch(function () { return 0; });
    }

    function resetApplied() {
      return eli.storage.getByPrefix(STORE_CONFIG, APPLIED_KEY_PREFIX).then(function (rows) {
        return Promise.all(rows.map(function (r) {
          return eli.storage.delete(STORE_CONFIG, r.key);
        }));
      });
    }

    // Replace kernel stub with full impl.
    window.eli.admin = {
      apiVersion: apiVersion,
      applyAll: applyAll, fetchOverrides: fetchOverrides, poll: poll,
      resetApplied: resetApplied, ACTIONS: ACTIONS,
      APPLIED_KEY_PREFIX: APPLIED_KEY_PREFIX,
    };
    // Defer the boot poll so the UI is ready when a `notice` action
    // calls showEliDialog. Running it at preload-time produced a silent
    // failure where the dialog never rendered but the applied-marker
    // was written anyway — burning the override forever. 3s is enough
    // for the dashboard to paint without delaying the kill-switch path
    // appreciably.
    setTimeout(function () { poll().catch(function () {}); }, 3000);
  }

  eli.log.event("tool", "eli_admin_initialized", {});
}
